public async Task HandleAsync(Message message, CancellationToken ct)
{
    await using var tx = await _db.Database.BeginTransactionAsync(ct);
    await _db.UpsertAsync(new InternalRecord(message.IdempotencyKey, message.Payload), ct);
    await _bus.PublishAsync(new RecordCreated(message.IdempotencyKey), ct);
    await tx.CommitAsync(ct);
    await _bus.AckAsync(message, ct);
}
